; colours: the scheme of each room; for a scheme the
; COLUBK table of the two frames of the water and
; the COLUPF table (a byte before its level's table)
SCHEME
        .byte $00,$00,$00,$00,$02,$02,$02,$01
        .byte $03,$03,$03,$03,$04,$05,$05,$05
CB0_LO
        .byte <(RC_1_0), <(RC_2_0), <(RC_FLAME+0)
        .byte <(RC_3_0), <(RC_4_0), <(RC_FLAME+1)
CB0_HI
        .byte >(RC_1_0), >(RC_2_0), >(RC_FLAME+0)
        .byte >(RC_3_0), >(RC_4_0), >(RC_FLAME+1)
CP_LO
        .byte <(RC_1_0-1), <(RC_2_0-1), <(RC_2_0-1)
        .byte <(RC_3_0-1), <(RC_4_0-1), <(RC_4_0-1)
CP_HI
        .byte >(RC_1_0-1), >(RC_2_0-1), >(RC_2_0-1)
        .byte >(RC_3_0-1), >(RC_4_0-1), >(RC_4_0-1)
; pointer bases of the figures: data + h - 160, so that
